298			t.Fatalf("补录较早证书应增加历史，共 %d 张", n)
299		}
300	
301		// 同一器具同一天不接受两张不同编号的证书，拒绝时保留原记录。
302		n := len(l.data.Certificates)
303		_, _, err := l.AddCertificate(cert("C-DUP", "2026-09-01", 0.2))
