308			t.Fatal("同日拒绝不应留下任何记录")
309		}
310	
311		// 最近证书超差或到期时，不得回退到更早的合格证书。
312		clock2 := &fakeClock{t: mustDate(t, "2026-10-02")}
313		l2 := newTestLedger(t, clock2)
314		mustRegister(t, l2, "M-1", "万用表", 0.5)
315		mustAddCert(t, l2, cert("C-BAD", "2026-09-01", 5))    // 最近，超差
316		mustAddCert(t, l2, cert("C-GOOD", "2026-01-01", 0.0)) // 更早，合格
317		_ = l2.SetStatus("M-1", StatusInUse)
318		d, _ := l2.RequestUse("M-1")
319		if d.Allowed || !containsReason(d.Reasons, "超差") {
320			t.Fatalf("最近证书超差不得回退到更早的合格证书，得到 %v", d.Reasons)
321		}
322	}
