1	package main
2	
3	import (
4		"encoding/json"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// rescheduleArgs 构造一条计划改期命令。
12	func rescheduleArgs(path, number, date, reason string) []string {
13		return []string{"reschedule", "-f", path,
14			"--number", number, "--date", date, "--reason", reason}
15	}
16	
17	// planArgs 构造一条建立校准计划命令（日期取较远的未来，避免依赖运行当天）。
18	func planArgs(path, instrument, number, date string) []string {
19		return []string{"plan", "-f", path,
20			"--instrument", instrument, "--number", number,
21			"--date", date, "--note", "周期校准"}
22	}
23	
24	// TestRescheduleSaveFailureIsFileErrorAndRecoverable 验证命令行改期在台账文件
25	// 无法写入时按文件读写错误报告、退出码 2、不显示“已改期”；失败后无需重开台账，
26	// 核对、计划查询与待办仍使用最后成功保存的日期，失败日期不进文件、不被此后的
27	// 成功写盘夹带。恢复可写后重新提交才生效，只新增一条从最后成功日期出发的记录。
28	func TestRescheduleSaveFailureIsFileErrorAndRecoverable(t *testing.T) {
29		dir := chdirTemp(t)
30		// 台账放在子目录里：把子目录改成只读即可挡住写临时文件与改名替换，
31		// 已存在的台账文件本身仍可读，查询不受影响。
32		sub := filepath.Join(dir, "只读目录")
33		if err := os.Mkdir(sub, 0o755); err != nil {
34			t.Fatal(err)
35		}
36		target := filepath.Join(sub, "ledger.json")
37		if r := runArgs(t, registerArgs(target, "M-1")...); r.code != 0 {
38			t.Fatalf("登记器具失败 code=%d stderr=%s", r.code, r.stderr)
39		}
40		if r := runArgs(t, planArgs(target, "M-1", "P-1", "2030-10-10")...); r.code != 0 {
41			t.Fatalf("建立计划失败 code=%d stderr=%s", r.code, r.stderr)
42		}
43		// 第一条成功改期：10-10 → 10-20。
44		if r := runArgs(t, rescheduleArgs(target, "P-1", "2030-10-20", "实验室排期冲突")...); r.code != 0 {
45			t.Fatalf("首次改期应成功 code=%d stderr=%s", r.code, r.stderr)
46		}
47	
48		// 目录只读：save 无法创建临时文件；测试结束后恢复权限便于清理。
49		if err := os.Chmod(sub, 0o555); err != nil {
50			t.Fatal(err)
51		}
52		t.Cleanup(func() { _ = os.Chmod(sub, 0o755) })
53	
54		// 合法改期 10-20 → 11-05 写盘失败：退出码 2，按文件读写错误报告，
55		// 不显示“已改期”，错误信息指出台账文件。
56		failArgs := rescheduleArgs(target, "P-1", "2030-11-05", "实验室改造延期")
57		r := runArgs(t, failArgs...)
58		if r.code != 2 {
59			t.Fatalf("改期写盘失败应按文件读写错误退出 2，得到 %d", r.code)
60		}
61		if strings.Contains(r.stdout, "已改期") {
62			t.Fatalf("写盘失败不得显示已改期：stdout=%q", r.stdout)
63		}
64		if !strings.Contains(r.stderr, target) {
65			t.Fatalf("错误应指出台账文件 %s，stderr=%q", target, r.stderr)
66		}
67	
68		// 与业务拒绝保持区别：日期不符合要求时即使目录只读也仍按业务拒绝退出 1，
69		// 不触碰写盘。
70		biz := runArgs(t, rescheduleArgs(target, "P-1", "2020-01-01", "想改到过去")...)
71		if biz.code != 1 {
72			t.Fatalf("早于当天的改期应业务拒绝退出 1，得到 %d（stderr=%s）", biz.code, biz.stderr)
73		}
74	
75		// 文件仍不可写时再次提交：仍退出 2，而不是成功。
76		if r2 := runArgs(t, failArgs...); r2.code != 2 || strings.Contains(r2.stdout, "已改期") {
77			t.Fatalf("再次提交应仍退出 2 且不显示已改期：code=%d stdout=%q", r2.code, r2.stdout)
78		}
79	
80		// 目录只读但台账可读：核对与待办仍使用最后成功保存的 10-20，看不到 11-05，
81		// 待办标记不按失败日期变化（对 2030-10-20 均为“未到计划日”）。
82		rv := runArgs(t, "review", "--id", "M-1", "-f", target, "--json")
83		if rv.code != 0 {
84			t.Fatalf("只读目录下核对应仍可进行：%s", rv.stderr)
85		}
86		if strings.Contains(rv.stdout, "2030-11-05") || strings.Contains(rv.stdout, "实验室改造延期") {
87			t.Fatalf("失败改期出现在核对结果中：%s", rv.stdout)
88		}
89		var view struct {
90			Plans []struct {
91				Number      string `json:"number"`
92				PlannedDate string `json:"planned_date"`
93				Marker      string `json:"marker"`
94				Changes     []struct {
95					From string `json:"from"`
96					To   string `json:"to"`
97				} `json:"changes"`
98			} `json:"plans"`
99		}
100		if err := json.Unmarshal([]byte(rv.stdout), &view); err != nil {
101			t.Fatalf("解析 review JSON 失败: %v\n%s", err, rv.stdout)
102		}
103		if len(view.Plans) != 1 || view.Plans[0].PlannedDate != "2030-10-20" ||
104			view.Plans[0].Marker != "未到计划日" || len(view.Plans[0].Changes) != 1 ||
105			view.Plans[0].Changes[0].To != "2030-10-20" {
106			t.Fatalf("核对应停留在最后成功保存的状态：%+v", view.Plans)
107		}
108		tv := runArgs(t, "todos", "-f", target, "--json")
109		if tv.code != 0 {
110			t.Fatalf("只读目录下待办查询应可进行：%s", tv.stderr)
111		}
112		var todos struct {
113			Todos []struct {
114				PlannedDate string `json:"planned_date"`
115			} `json:"todos"`
116		}
117		if err := json.Unmarshal([]byte(tv.stdout), &todos); err != nil {
118			t.Fatalf("解析 todos JSON 失败: %v\n%s", err, tv.stdout)
119		}
120		if len(todos.Todos) != 1 || todos.Todos[0].PlannedDate != "2030-10-20" {
121			t.Fatalf("待办应仍按 2030-10-20：%+v", todos.Todos)
122		}
123		raw, err := os.ReadFile(target)
124		if err != nil {
125			t.Fatalf("读取台账文件: %v", err)
126		}
127		if strings.Contains(string(raw), "2030-11-05") {
128			t.Fatalf("失败日期已存在于台账文件：\n%s", raw)
129		}
130	
131		// 恢复目录可写：先做一次无关的正常操作（器具停用）并保存成功，
132		// 失败的改期不能被顺带写入。
