142		}
143		if strings.Contains(string(raw), "2030-11-05") || strings.Contains(string(raw), "实验室改造延期") {
144			t.Fatalf("失败改期被随后成功的写盘顺带写入文件：\n%s", raw)
145		}
146	
147		// 停用器具的计划仍可改期：重新提交到 11-08 才成功，当前日期改为 11-08，
148		// 只新增一条 10-20 → 11-08，历史共两条，任何位置都没有 11-05。
149		ok := runArgs(t, rescheduleArgs(target, "P-1", "2030-11-08", "改造完成重新排期")...)
150		if ok.code != 0 || !strings.Contains(ok.stdout, "已改期为 2030-11-08") ||
151			!strings.Contains(ok.stdout, "第 2 次改期") {
152			t.Fatalf("恢复后改期应成功且为第 2 次改期：code=%d stdout=%q stderr=%s",
153				ok.code, ok.stdout, ok.stderr)
154		}
155		after := runArgs(t, "review", "--id", "M-1", "-f", target, "--json")
156		var final struct {
157			Plans []struct {
158				PlannedDate string `json:"planned_date"`
159				Status      string `json:"status"`
160				Changes     []struct {
