162					To     string `json:"to"`
163					Reason string `json:"reason"`
164				} `json:"changes"`
165			} `json:"plans"`
166		}
167		if err := json.Unmarshal([]byte(after.stdout), &final); err != nil {
168			t.Fatalf("解析 review JSON 失败: %v\n%s", err, after.stdout)
169		}
170		if len(final.Plans) != 1 {
171			t.Fatalf("应只有一项计划：%+v", final.Plans)
172		}
