17		if err != nil {
18			t.Fatalf("取工作目录: %v", err)
19		}
20		if err := os.Chdir(dir); err != nil {
21			t.Fatalf("切换临时目录: %v", err)
22		}
23		t.Cleanup(func() { _ = os.Chdir(orig) })
24		return dir
25	}
26	
27	type result struct {
28		code   int
29		stdout string
30		stderr string
31	}
32	
33	func runArgs(t *testing.T, args ...string) result {
34		t.Helper()
35		var out, errBuf bytes.Buffer
36		code := run(args, &out, &errBuf)
37		return result{code: code, stdout: out.String(), stderr: errBuf.String()}
38	}
39	
40	func registerArgs(path, id string) []string {
41		return []string{"register", "-f", path, "--id", id, "--name", "万用表-" + id, "--allowed", "0.5"}
42	}
43	
44	func fileExists(t *testing.T, path string) bool {
45		t.Helper()
46		_, err := os.Stat(path)
47		if err == nil {
48			return true
49		}
50		if os.IsNotExist(err) {
51			return false
52		}
53		t.Fatalf("stat %s: %v", path, err)
54		return false
55	}
56	
57	func readUsageCount(t *testing.T, path string) int {
58		t.Helper()
59		raw, err := os.ReadFile(path)
60		if err != nil {
61			t.Fatalf("读取台账 %s: %v", path, err)
62		}
63		var data struct {
64			Usage []json.RawMessage `json:"usage"`
65		}
66		if err := json.Unmarshal(raw, &data); err != nil {
67			t.Fatalf("解析台账 %s: %v", path, err)
68		}
69		return len(data.Usage)
70	}
71	
72	// 子命令之后给出 -f 时，记录必须落到该文件，而不是默认 ledger.json。
73	func TestFileFlagAfterSubcommandSelectsTarget(t *testing.T) {
74		dir := chdirTemp(t)
75		target := filepath.Join(dir, "other.json")
