95	// 多个文件参数交错出现时，按命令行顺序以最后一次为准。
96	func TestMultipleFileFlagsLastWins(t *testing.T) {
97		dir := chdirTemp(t)
98		a := filepath.Join(dir, "a.json")
99		b := filepath.Join(dir, "b.json")
100		c := filepath.Join(dir, "含 空格 的目录", "c.json")
101	
102		r := runArgs(t,
103			"-f", a,
104			"register",
105			"--id", "M-1",
106			"--file", b,
107			"--name", "万用表",
108			"--allowed", "0.5",
109			"-f", c,
110		)
111		if r.code != 0 {
112			t.Fatalf("register code=%d stderr=%s", r.code, r.stderr)
113		}
114		if fileExists(t, a) || fileExists(t, b) {
115			t.Fatal("被覆盖的文件路径不应被创建或读取")
116		}
117		if !fileExists(t, c) {
118			t.Fatal("最后一次指定的路径才应是目标台账")
119		}
120	
121		// 短名与长名混合、按命令行顺序覆盖：中间给过不存在的路径，最后一次
122		// 落在真正有数据的 c；再验证最后一次落到空路径时不会回头使用 c。
123		none := filepath.Join(dir, "none.json")
124		r2 := runArgs(t, "list", "--file", a, "-f", none, "--file", c)
125		if r2.code != 0 || !strings.Contains(r2.stdout, "M-1") {
126			t.Fatalf("短长名混合的 last-wins 查询失败 code=%d stdout=%q", r2.code, r2.stdout)
127		}
128		r3 := runArgs(t, "list", "-f", c, "--file", none)
129		if r3.code != 0 || strings.Contains(r3.stdout, "M-1") {
130			t.Fatalf("最后一次为空路径时不应再使用前面的 c，stdout=%q", r3.stdout)
131		}
132		if fileExists(t, none) {
133			t.Fatal("查询不应创建仅作为中间值出现过的文件")
134		}
135	}
136	
137	// --file=路径、-f路径、单横线长名等写法都可用，路径中的中文与空格保持完整。
138	func TestFileFlagEquivalentForms(t *testing.T) {
139		dir := chdirTemp(t)
140		cases := [][]string{
141			{"register", "--id", "EQ", "--name", "n", "--allowed", "1",
142				"--file=" + filepath.Join(dir, "等号 长名.json")},
143			{"register", "--id", "AT", "--name", "n", "--allowed", "1",
144				"-f" + filepath.Join(dir, "短名粘连.json")},
145			{"register", "--id", "DS", "--name", "n", "--allowed", "1",
146				"-file=" + filepath.Join(dir, "单横线.json")},
147			{"-f" + filepath.Join(dir, "前置 粘连.json"),
148				"register", "--id", "FS", "--name", "器具 名称", "--allowed", "1"},
149		}
150		for i, args := range cases {
151			r := runArgs(t, args...)
152			if r.code != 0 {
153				t.Fatalf("写法 %d 失败 code=%d stderr=%s", i, r.code, r.stderr)
154			}
155		}
156		for _, name := range []string{"等号 长名.json", "短名粘连.json", "单横线.json", "前置 粘连.json"} {
157			if !fileExists(t, filepath.Join(dir, name)) {
158				t.Fatalf("文件 %q 未被创建，路径中的中文或空格被破坏", name)
159			}
160		}
161	}
162	
163	// 查询不存在的台账按空台账处理，且不得仅为查询创建文件。
164	func TestQueryMissingFileDoesNotCreate(t *testing.T) {
165		dir := chdirTemp(t)
166		missing := filepath.Join(dir, "absent.json")
167	
168		if r := runArgs(t, "list", "-f", missing); r.code != 0 {
169			t.Fatalf("空台账 list 应成功，code=%d stderr=%s", r.code, r.stderr)
170		}
171		if r := runArgs(t, "todos", "-f", missing); r.code != 0 || !strings.Contains(r.stdout, "无待办") {
172			t.Fatalf("空台账 todos 异常 code=%d stdout=%q", r.code, r.stdout)
173		}
174		if r := runArgs(t, "review", "--id", "X", "-f", missing); r.code != 1 {
175			t.Fatalf("空台账查不存在器具应退出 1，得到 %d", r.code)
176		}
177		if fileExists(t, missing) {
178			t.Fatal("查询不应创建台账文件")
179		}
180	
181		// 成功写入后文件才出现，并能继续查阅此前保存的数据。
182		if r := runArgs(t, registerArgs(missing, "M-9")...); r.code != 0 {
